pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat:") {
        return sequence
            .parse::<u32>()
            .map(Msg::Heartbeat)
            .map_err(|_| "invalid heartbeat".into());
    }
    if let Some(name) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(name.into()));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{name}"),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{sequence}"),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_uses_v2_envelope() {
        let msg = Msg::Hello("world".into());
        assert_eq!(encode(&msg), "v:2|hello:world");
        assert!(matches!(decode("v:2|hello:world"), Ok(Msg::Hello(name)) if name == "world"));
    }

    #[test]
    fn heartbeat_preserves_sequence_number() {
        let msg = Msg::Heartbeat(42);
        assert_eq!(encode(&msg), "v:2|heartbeat:42");
        assert!(matches!(decode("v:2|heartbeat:42"), Ok(Msg::Heartbeat(42))));
    }

    #[test]
    fn heartbeat_roundtrip() {
        let msg = Msg::Heartbeat(42);
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Heartbeat(42))));
    }

    #[test]
    fn invalid_heartbeat_is_rejected() {
        assert!(decode("v:2|heartbeat:not-a-number").is_err());
    }
}
